  'home.enterAProjectGoal': ['프로젝트 목표를 입력하면 워크플로우를 먼저 만들어요. PM 지정과 수동 배정은 필요 없어요.', 'Enter a project goal and the workflow is created first. No PM assignment or manual assignment is needed.'],
  'home.describeTheBugOr': ['오류·개선 요청과 재현 방법을 적고 시작하기를 누르세요. 요청 범위에서 바로 진행합니다.', 'Describe the bug or improvement request and how to reproduce it, then click Get started. It proceeds right away within the request scope.'],
  'home.checkTheScopeTask': ['범위·작업 순서·산출물·완료 기준을 확인한 뒤 이 워크플로우로 시작을 누르세요.', 'Check the scope, task order, deliverables and completion criteria, then press Start with this workflow.'],
  'home.intakeAnalysisImpactCheck': ['접수·분석 → 영향 확인 → 수정 → 회귀 검증 → 처리 보고. 질문과 실행 승인에는 이 화면에서 답하세요.', 'Intake & analysis → Impact check → Fix → Regression test → Resolution report. Answer questions and execution approvals on this screen.'],
  'home.checkingExecutionTools': ['실행 도구 확인 중…', 'Checking execution tools…'],
  'home.installThisCliAnd': ['이 CLI를 설치하고 로그인 또는 API 설정을 마친 뒤 도구 다시 확인을 누르세요. 설치 후에도 보이지 않으면 init으로 대시보드를 다시 실행하세요.', 'Install this CLI and finish signing in or API setup, then press Recheck tools. If it still doesn’t appear after installing, restart the dashboard with init.'],
  'home.usageCountsAgainstYour': ['Antigravity 계정의 사용량이 적용됩니다. 새 권한 요청은 웹에서 승인할 수 없어 터미널 설정 확인이 필요합니다.', 'Usage counts against your Antigravity account. New permission requests can’t be approved on the web, so check the terminal settings.'],
  'home.installationFoundFinishSigning': ['{0} 설치 확인됨 · 로그인 또는 API 설정은 해당 CLI에서 마쳐 주세요. 해당 계정의 한도·비용이 적용됩니다.', '{0} installation found · Finish signing in or API setup in that CLI. That account’s limits and costs apply.'],
  'home.checkingTheAiTools': ['설치한 AI 도구를 확인하고 있어요.', 'Checking the AI tools you have installed.'],
  'home.installationFoundYouCan': ['{0} 설치 확인됨. 아래 실행 도구에서 바꿀 수 있어요. 로그인 여부는 실행할 때 확인합니다.', '{0} installation found. You can change it under Execution tool below. Sign-in is checked when it runs.'],
  'home.couldntFindTheSelected': ['선택한 도구를 찾지 못했어요. 아래에서 설치된 도구를 고르거나 CLI 설치 후 도구 다시 확인을 누르세요.', 'Couldn’t find the selected tool. Pick an installed tool below, or install the CLI and press Recheck tools.'],
  'home.thisRequestCantBe': ['이 요청은 이어갈 수 없어요. 새 요청 만들기를 눌러 주세요', 'This request can’t be continued. Press New request.'],
