  'home.beforeProceedingCheckThe': ['진행 전에 범위·작업 순서·완료 기준을 확인하세요. 수정할 점은 아래 입력창에 보내세요.', 'Before proceeding, check the scope, task order and completion criteria. Send anything to change in the box below.'],
  'home.me': ['나', 'Me'],
  'home.sessionsJoinedWaitingOr': ['{0}개 세션 참여 · {1}개 대기·자리 비움', '{0} sessions joined · {1} waiting or away'],
  'home.enterCommandsInEach': ['명령은 셸 터미널이 아닌 각 도구의 AI 대화창에 입력하세요. Codex CLI는 $wax:work처럼 $로 스킬을 호출합니다. Codex 입력창의 @는 파일 첨부이며 wax 채널의 @이름 알림과는 다릅니다.', 'Enter commands in each tool’s AI chat, not in a shell terminal. Codex CLI calls skills with $, like $wax:work. In the Codex input box, @ attaches a file and is different from the @name mention in the wax channel.'],
  'home.inANewAi': ['새 AI 세션에서', 'In a new AI session'],
  'home.enterThisCommandIn': ['이 명령은 각 도구의 AI 대화창에 입력합니다', 'Enter this command in each tool’s AI chat'],
  'home.theresNoPmSo': ['PM이 없어 수동 업무 배정을 시작하지 못하고 있어요. PM으로 쓸 AI 세션에서 아래 명령과 목표를 입력하세요.', 'There’s no PM, so manual assignment can’t start. In the AI session you want as PM, enter the command and goal below.'],
  'home.isThePmIn': ['{0}님이 PM입니다. 상세 기록의 업무 배정에서 작업·담당·현재 단계를 선택하세요.', '{0} is the PM. In Detailed records, choose the task, owner and current stage under Assignment.'],
  'home.thePmIsGive': ['PM은 {0}입니다. 이 세션에 목표를 전달하면 작업을 만들고 첫 단계를 배정합니다.', 'The PM is {0}. Give this session a goal and it will create the task and assign the first stage.'],
