  'home.noTerminalAiSessions': ['참여한 터미널 AI 세션이 없습니다. 위의 한 줄 요청은 join 없이 바로 시작할 수 있어요.', 'No terminal AI sessions have joined. The one-line request above can start right away without join.'],
