  'home.ifTheCliDoesnt': ['CLI가 보이지 않으면 설치 후 init으로 대시보드를 다시 실행하세요.', 'If the CLI doesn’t appear, install it and restart the dashboard with init.'],
  'home.sendOrClearThe': ['입력 중인 수정 내용을 먼저 보내거나 비운 뒤 워크플로우를 시작하세요.', 'Send or clear the edit you’re typing, then start the workflow.'],

  'notify.off': ['알림 켜기', 'Turn on notifications'],
  'notify.on': ['알림 켜짐', 'Notifications on'],
  'notify.offHelp': ['이 탭을 보고 있지 않을 때 AI 질문, 실행 승인 요청, 단계 완료, 트리거 제안을 브라우저 알림으로 받습니다. 처음 누르면 브라우저가 권한을 묻습니다.', 'Get browser notifications for AI questions, execution approval requests, completed phases and trigger proposals while you are not looking at this tab. The browser asks for permission the first time.'],
  'notify.onHelp': ['누르면 알림을 끕니다. 켜고 끈 선택은 이 브라우저에만 저장됩니다.', 'Click to turn notifications off. The choice is saved in this browser only.'],
  'notify.unsupported': ['알림 미지원', 'Notifications unsupported'],
