  'notify.blocked': ['알림 차단됨', 'Notifications blocked'],
  'notify.blockedHelp': ['브라우저가 이 사이트의 알림을 막았습니다. 주소창의 사이트 설정에서 알림을 허용한 뒤 새로고침하세요.', 'The browser blocked notifications for this site. Allow notifications in the site settings next to the address bar, then reload.'],
