  'proposals.title': ['트리거 제안', 'Trigger proposals'],
  'proposals.intro': ['트리거가 만든 요청 제안입니다. 수락해야 AI가 시작합니다. 문구·도구·모드를 고친 뒤 수락하거나 버리세요.', 'Request proposals made by triggers. AI starts only after you accept. Edit the text, tool or mode, then accept or dismiss.'],
