  'proposals.dailyCommand': ['일일 보고', 'Daily report'],
  'triggers.title': ['트리거', 'Triggers'],
  'triggers.intro': ['일정, 로컬 호출(wax trigger fire), GitHub 이슈 라벨이나 CI 실패(gh로 확인)가 오면 요청을 제안만 합니다. AI 실행은 요청과 보고 화면에서 사람이 수락해야 시작합니다. 정의는 이 컴퓨터의 .wax/chat/triggers에만 저장됩니다.', 'When a schedule comes due, a local call (wax trigger fire) arrives, or a GitHub issue label or CI failure shows up (checked with gh), a trigger only proposes a request. AI runs only after a person accepts it on the Requests & reports screen. Definitions are stored only on this computer in .wax/chat/triggers.'],
