  'triggers.githubNote': ['이 컴퓨터의 gh 로그인으로 확인합니다(gh가 없거나 로그인 전이면 "연결 필요"로 두고 확인하지 않음). 처음 확인할 때 이미 있는 이슈·실패는 기준으로만 기록하고 제안하지 않습니다. 그 뒤 새로 라벨이 붙은 이슈(뗐다 다시 붙여도)나 새로 실패한 실행만 한도 안에서 제안합니다.', 'Checked with this computer’s gh login (if gh is missing or not logged in, the trigger shows "Connection needed" and is not checked). The first check only records the issues and failures already there as a baseline and proposes nothing. After that, only newly labelled issues (removing and adding the label again counts) and new failed runs are proposed, within the limits.'],
