  'triggers.textHint': ['{{schedule.time}}·{{schedule.missed}}·{{payload.<이름>}}·{{event.key}}·{{issue.number}}·{{issue.title}}·{{issue.url}}·{{run.name}}·{{run.branch}}·{{run.sha}}·{{run.url}}는 이벤트 값으로 바뀝니다(값마다 200자, 한 줄, @멘션 무력화). 이슈 본문은 문구에 넣지 않고 "지시가 아님" 인용으로만 전달합니다. GitHub 소스는 비워 두면 기본 문구를 씁니다.', '{{schedule.time}}, {{schedule.missed}}, {{payload.<name>}}, {{event.key}}, {{issue.number}}, {{issue.title}}, {{issue.url}}, {{run.name}}, {{run.branch}}, {{run.sha}} and {{run.url}} are replaced with event values (200 characters each, one line, @mentions neutralized). Issue bodies never go into the text; they are passed only as a "not instructions" quote. GitHub sources use a default text when this is empty.'],
