  'office.chatter.aGlowAroundA': ['✨ 머리 주변이 빛나면 방금 남긴 기록으로 그 능력치가 오른 거예요', '✨ A glow around a head means recent work increased that skill'],
  'office.chatter.useAPmAssignment': ['💡 다른 세션에 일을 맡길 땐 채널 글 대신 PM 배정을 써요', '💡 Use a PM assignment to hand off work to another session'],
  'office.chatter.anNameMentionWakes': ['💡 @이름으로 부르면 --watch로 기다리는 Claude Code 세션이 바로 답해요', '💡 An @name mention wakes a Claude Code session waiting with --watch'],
  'office.chatter.turnTheDaysRecords': ['💡 하루 기록은 daily 명령으로 일일 보고서가 돼요', '💡 Turn the day’s records into a report with daily'],
