  'office.chatter.floorsGoFromDiscussion': ['💡 건물은 아래에서 위로 회의 → 개발 → 검토 → 보고 순서예요', '💡 Floors go from discussion to development, review and reporting'],
  'office.chatter.thePmWorksIn': ['💡 PM은 사장실에 있어요. PM에게 메시지를 보내면 잠깐 방문하러 가요', '💡 The PM works in the CEO’s office. Send a message to visit'],
  'office.chatter.idleSessionsRelaxAnd': ['💡 쉬는 세션은 옥상 정원에 올라가 담소를 나눠요', '💡 Idle sessions relax and chat on the roof'],
  'office.chatter.selectAWhiteboardFor': ['💡 화이트보드를 누르면 작업별 의견·질문·결정 노트를 볼 수 있어요', '💡 Select a whiteboard for task opinions, questions and decisions'],
  'office.chatter.after3QuietMinutes': ['💡 3분 넘게 조용하면 "…", 10분이 지나면 책상에서 잠들어요', '💡 After 3 quiet minutes a session shows ‘…’; after 10 it sleeps'],
  'office.chatter.seeHelpInThe': ['📖 더 자세한 건 위쪽 메뉴의 도움말에 있어요', '📖 See Help in the top menu for more'],
  'office.chatter.theFirstSessionUses': ['🆕 처음 세션은 init 한 번으로 참여·작업·대시보드·PM을 정하고, 다른 세션은 join으로 들어와요', '🆕 The first session uses init to prepare its task, dashboard and PM; others join'],
  'office.chatter.duplicateSessionNamesGet': ['🆕 같은 이름의 세션이 이미 있으면 -2, -3을 붙여 따로 들어와요', '🆕 Duplicate session names get -2, -3 and so on'],
