  'office.chatter.theCeoGivesDirection': ['대표가 지시하면 PM이 선택지와 추천안을 드리고, 대표가 결정하면 PM이 업무를 배정해요', 'The CEO gives direction, the PM offers options and recommendations, then assigns work after the decision'],
  'office.chatter.thePmReportsProgress': ['진행 상황과 지연은 PM이 대표에게 보고해요. pm 명령을 다시 부르면 보고를 받을 수 있어요', 'The PM reports progress and delays to the CEO. Run pm again for a report'],
  'office.chatter.onlyThePmCan': ['업무 배정은 PM만 할 수 있어요', 'Only the PM can assign work'],
  'office.chatter.assignmentsAuthorizeThatStage': ['배정은 그 단계의 작업만 허락해요. 대표 지시가 늘 우선이에요', 'Assignments authorize that stage only. CEO instructions always take priority'],
  'office.chatter.assignedSessionsStartWith': ['배정받은 세션은 work 명령으로 시작하고, 끝나면 업무 상태로 결과를 남겨요', 'Assigned sessions start with work and report the result through assignment status'],
