  'office.chatter.runTestsAfterA': ['고친 다음엔 꼭 테스트를 돌려서 근거로 남겨야 한다네. 말로만 "됐어요"는 통과가 아니야', 'Run tests after a fix and keep the evidence. Saying ‘done’ is not a pass'],
  'office.chatter.reproduceABugWith': ['버그는 먼저 실패하는 테스트로 재현하고, 그다음에 고치는 게 순서지', 'Reproduce a bug with a failing test, then fix it'],
  'office.chatter.aDifferentSessionShould': ['검토는 만든 사람 말고 다른 세션이 하는 게 좋아. 내 눈엔 내 실수가 안 보이거든', 'A different session should review the work. It is easy to miss your own mistakes'],
  'office.chatter.boundariesEmptyValuesSlow': ['경계값·빈 값·느린 네트워크… 손님은 늘 예상 못 한 길로 온다네', 'Boundaries, empty values, slow networks… users find surprising paths'],
  'office.chatter.failingReviewTestsCount': ['검토에서 찾은 실패 테스트는 버그 발견으로 기록돼. 부끄러운 게 아니라 훈장이지', 'Failing review tests count as bugs found. That is an achievement'],
