  'office.chatter.reviewThePreviewAnd': ['✏️ 미리보기를 보고 수정할 점을 적으면 다음 버전으로 이어져요', '✏️ Review the preview and request changes for the next version'],
  'office.chatter.approveYourChosenVersion': ['📦 마음에 드는 버전을 확정한 뒤 개발에 인계해요', '📦 Approve your chosen version, then hand it to development'],
  'office.chatter.jennysDesignGuide': ['제니의 디자인 안내', 'Jenny’s design guide'],
  'office.chatter.illGuideYouThrough': ['디자인실에서 도구 연결부터 시안 검토와 개발 인계까지 안내해 드려요.', 'I’ll guide you through connecting tools, reviewing designs and handing them to development.'],
  'office.chatter.gettingStarted': ['처음 시작하기', 'Getting started'],
  'office.chatter.openDesignDeliverablesAnd': ['디자인실 제작물을 열고 Figma 프레임 링크나 프로젝트 안의 Blender 파일·장면·컬렉션을 등록해요.', 'Open Design deliverables and register a Figma frame link or a Blender file, scene and collection in your project.'],
  'office.chatter.connectTheMcpFor': ['사용할 코딩 도구의 MCP를 연결하고 연결 검사에서 읽기·쓰기 가능 여부를 확인해요.', 'Connect the MCP for your coding tool, then check read and write access.'],
  'office.chatter.chooseADesignTarget': ['디자인 대상과 담당 AI를 고르고 만들 화면이나 소품, 필요한 요소와 분위기를 적어 제작을 요청해요.', 'Choose a design target and AI, describe the screen or prop, its required elements and style, then request creation.'],
  'office.chatter.reviewAndHandoff': ['시안 검토와 인계', 'Review and handoff'],
  'office.chatter.checkTheFinishedPreview': ['완성된 미리보기와 바뀐 점을 확인해요.', 'Check the finished preview and the changes.'],
  'office.chatter.describeSpecificChangesTo': ['수정할 부분을 구체적으로 적어 다음 버전을 요청해요. 이전 버전도 다시 볼 수 있어요.', 'Describe specific changes to request the next version. Previous versions remain available.'],
  'office.chatter.approveYourChosenVersionAnd': ['마음에 드는 버전을 확정하고 개발에 인계해요. 연결한 작업에서 확정 시안과 인계 내용을 이어 볼 수 있어요.', 'Approve your chosen version and hand it to development. The linked task keeps the approved design and handoff details.'],
  'office.chatter.choosingATool': ['도구 선택', 'Choosing a tool'],
  'office.chatter.figmaForScreenLayouts': ['Figma: 화면 구성과 UI를 만들 때 사용해요. 작업할 프레임의 링크를 준비해 주세요.', 'Figma: for screen layouts and UI. Prepare a link to the frame you want to work on.'],
  'office.chatter.blenderFor3dProps': ['Blender: 3D 소품과 장면을 만들 때 사용해요. 프로젝트 안의 .blend 파일을 열고 장면·컬렉션을 지정해 주세요.', 'Blender: for 3D props and scenes. Open a .blend file in your project and specify its scene and collection.'],
  'office.chatter.iExplainTheWorkflow': ['저는 사용 순서를 안내해요. 실제 제작은 연결 검사를 통과한 도구에서 선택한 AI가 수행해요.', 'I explain the workflow. Your chosen AI creates the design using a tool that has passed the connection check.'],
