  'office.chatter.seeHowTheProjects': ['프로젝트 작업이 어디까지 왔는지 알려 드려요.', 'See how the project’s tasks are progressing.'],
  'office.chatter.stagesByTask': ['작업별 단계', 'Stages by task'],
  'office.chatter.noTasksYetSelect': ['아직 작업이 없어요. 대시보드의 "새 작업 만들기"로 시작해요.', 'No tasks yet. Select ‘New task’ in the dashboard.'],
