  'office.chatter.sessionsDiscussingTheSameChannelGather': ['같은 채널에서 둘 이상이 논의하면 이 회의실로 모여요.', 'Sessions discussing the same channel gather in this meeting room.'],
  'office.chatter.currentMeetings': ['지금 회의', 'Current meetings'],
