  'office.chatter.rinasToolNews': ['리나의 도구 소식', 'Rina’s tool news'],
  'office.chatter.newCodingToolFeatures': ['코딩 도구들의 새 기능과 이 PC에 설치된 버전을 알려 드려요.', 'New coding-tool features and versions installed on this computer.'],
  'office.chatter.toolsOnThisComputer': ['이 PC에 설치된 도구', 'Tools on this computer'],
  'office.chatter.newsChecked': ['소식 확인', 'News checked'],
  'office.chatter.thisScreenUsesBundled': ['이 화면은 기본 자료를 사용해요. 공개 데모는 외부에 접속하지 않아요.', 'This screen uses bundled data. The public demo does not contact external services.'],
  'office.chatter.officialReleasesAreChecked': ['공식 릴리스는 화면을 사용하는 동안 1시간 간격으로 확인해요. 조회에 실패하면 마지막 자료를 유지하고 5분 후 다시 시도해요.', 'Official releases are checked hourly while the screen is open. Failed checks keep the last snapshot and retry after five minutes.'],
  'office.chatter.goodToKnow': ['알아 두기', 'Good to know'],
  'office.chatter.checkOfficialChangelogsFor': ['새 릴리스는 공식 변경 이력에서 확인해요. 검토된 한국어 요약이 아직 없는 새 소식은 공식 원문으로 표시해요. 설치 버전과 소식 기준은 별도로 보여 드려요.', 'Check official changelogs for new releases. News without a reviewed summary links to its official source. Installed versions and news snapshots are shown separately.'],
  'office.chatter.installedVersionsAreChecked': ['설치 버전은 이 PC의 --version을 10분마다 읽어요. 아래 버튼으로 설치 버전과 공식 소식을 각각 즉시 다시 확인할 수 있어요.', 'Installed versions are checked with --version every ten minutes. Use the buttons below to recheck versions and official news separately.'],
  'office.chatter.officialNewsChecksSend': ['공식 소식 조회에는 프로젝트·설치 버전·세션 정보를 보내지 않아요. 오프라인으로 쓰려면 서버 실행 시 WAX_TOOL_NEWS=off를 설정하세요.', 'Official news checks send no project, installed-version or session data. Set WAX_TOOL_NEWS=off to stay offline.'],
