  'compare.handoff': ['디자인 인계 v{0} 미리보기 {1}는 폭·스크롤·상태 라벨이 없어 짝짓지 않았습니다.', 'Design handoff v{0} preview {1} has no viewport, scroll or state labels, so it was not paired.'],
