  'prBody.freshnessNote': ['_관찰 기록이며 판정이 아닙니다. 바뀐 파일이 위 근거에 영향을 주면 테스트를 다시 실행하세요._', '_An observation, not a verdict. Re-run the tests if these changes affect the evidence above._'],
  'prBody.footer': ['_wax pr-body가 로컬 기록만으로 만든 초안입니다. 기록에 없는 내용은 없다고 적었습니다._', '_Drafted by wax pr-body from local records only. Anything missing from the records is stated as missing._'],
