  'pmLoop.judge.timeout': ['{1}의 {0}이(가) 실행 시간 상한 {2}분을 넘어 멈췄습니다. 사람이 정합니다.', 'The {0} by {1} passed the {2}-minute run limit and was stopped. A person decides.'],
